"use client";

import { useReducedMotion } from "motion/react";
import { useId, useRef, useState } from "react";

import { Button } from "@/components/ui/button";

import { formatMoney, formatWhole } from "../lib/format";
import { BlockFrame } from "../parts/block-frame";
import { PlayerPlayFilledIcon, RefreshIcon } from "../parts/icons";
import { RollingText } from "../parts/rolling-text";
import { PauseIcon } from "./icons";
import { useInView } from "./lib/use-in-view";
import { useTokenColors } from "./lib/use-token-colors";
import { CityList } from "./revenue-globe/city-list";
import {
  CITIES,
  clockLabel,
  DAY_LABEL,
  HEAD_OFFICE,
  readDay,
} from "./revenue-globe/data";
import { DayTimeline } from "./revenue-globe/day-timeline";
import { GlobeCanvas } from "./revenue-globe/globe-canvas";
import { useDayClock } from "./revenue-globe/use-day-clock";

/**
 * Card payments from Fernhill clinics around the world, drawn as arcs to the
 * head office as they arrive. A person can spin the globe, pick a city to
 * fly to it, replay the day from midnight, pause, or scrub the timeline.
 * The figures and the city list say in text what the globe shows.
 */
export function RevenueGlobe({ className }: { className?: string }) {
  const titleId = useId();
  const box = useRef<HTMLDivElement>(null);
  const inView = useInView(box);
  const colors = useTokenColors(box);
  const reduceMotion = useReducedMotion() ?? false;
  const { clock, replay, togglePlaying, scrub, goLive } = useDayClock(inView);
  const [selected, setSelected] = useState<number | null>(null);

  const minute = Math.floor(clock.minute);
  const day = readDay(minute);
  const leader = day.cities.reduce(
    (best, city, index) =>
      city.revenue > (day.cities[best]?.revenue ?? 0) ? index : best,
    0,
  );
  const selectedCity = selected === null ? null : CITIES[selected];

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3 px-5 pt-5">
        <div className="min-w-0">
          <h2 id={titleId} className="text-base font-semibold">
            Payments arriving in {HEAD_OFFICE.name}
          </h2>
          <p className="text-sm text-muted-foreground">
            {CITIES.length} cities settle to one head office. {DAY_LABEL}.
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {clock.live ? (
            <span className="inline-flex items-center gap-1.5 rounded-full bg-marketing-green-surface px-2.5 py-1 text-xs font-medium text-marketing-green-ink">
              <span
                aria-hidden="true"
                className="size-1.5 rounded-full bg-current motion-safe:animate-pulse"
              />
              Live
            </span>
          ) : null}
          <span
            className="text-sm font-medium tabular-nums"
            aria-label={`Showing ${clockLabel(minute)}`}
          >
            {clockLabel(minute)}
          </span>
          {reduceMotion ? null : (
            <Button variant="outline" size="sm" onClick={replay}>
              <RefreshIcon aria-hidden="true" className="size-4" />
              Replay today
            </Button>
          )}
          <Button
            variant="outline"
            size="icon"
            aria-label={clock.playing ? "Pause" : "Play"}
            onClick={togglePlaying}
          >
            {clock.playing ? (
              <PauseIcon className="size-4" />
            ) : (
              <PlayerPlayFilledIcon aria-hidden="true" className="size-4" />
            )}
          </Button>
        </div>
      </header>

      <div
        ref={box}
        className="grid items-center gap-4 px-5 py-4 @2xl:grid-cols-[1fr_16rem]"
      >
        <GlobeCanvas
          minute={minute}
          selected={selected}
          onSelect={setSelected}
          cityTotals={day.cities}
          colors={colors}
          reduceMotion={reduceMotion}
          active={inView}
          label={`Globe of payments to ${HEAD_OFFICE.name}. Arrows spin it, Escape clears the chosen city.`}
        />
        <div className="flex flex-col gap-4">
          <dl className="grid grid-cols-2 gap-3">
            <div className="flex flex-col gap-0.5">
              <dt className="text-sm text-muted-foreground">Revenue today</dt>
              <dd>
                <RollingText
                  text={formatMoney(day.revenue)}
                  className="text-2xl font-semibold tracking-tight"
                />
              </dd>
            </div>
            <div className="flex flex-col gap-0.5">
              <dt className="text-sm text-muted-foreground">Payments</dt>
              <dd>
                <RollingText
                  text={formatWhole(day.count)}
                  className="text-2xl font-semibold tracking-tight"
                />
              </dd>
            </div>
          </dl>
          <CityList
            totals={day.cities}
            selected={selected}
            onSelect={setSelected}
          />
        </div>
      </div>

      {/* Only the city's name is announced: the figures after it change every minute and would talk over the page. */}
      <p className="px-5 pb-2 text-sm text-muted-foreground">
        <span role="status">
          {selectedCity
            ? `${selectedCity.name} selected.`
            : `${CITIES[leader]?.name} has sent the most so far.`}
        </span>{" "}
        {selectedCity
          ? `${formatMoney(day.cities[selected!]?.revenue ?? 0)} from ${formatWhole(day.cities[selected!]?.payments ?? 0)} payments by ${clockLabel(minute)}.`
          : `${formatMoney(day.revenue)} by ${clockLabel(minute)}.`}
      </p>
      <DayTimeline
        minute={clock.minute}
        liveMinute={clock.liveMinute}
        hours={day.hours}
        onScrub={scrub}
        onLive={goLive}
      />
    </BlockFrame>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

