"use client";

import { type RefObject, useEffect, useState } from "react";

/**
 * Says whether the element is on screen, so a showpiece can stop drawing
 * frames while it is scrolled away. It reads false until the first check.
 */
export function useInView(ref: RefObject<Element | null>): boolean {
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(
      ([entry]) => setInView(entry?.isIntersecting ?? false),
      { rootMargin: "64px" },
    );
    observer.observe(node);
    return () => observer.disconnect();
  }, [ref]);
  return inView;
}

"use client";

import { type RefObject, useEffect, useState } from "react";

/** The theme colours a canvas needs, read from the design system's tokens. */
export interface TokenColors {
  chart: [string, string, string, string, string];
  foreground: string;
  muted: string;
  border: string;
  card: string;
}

const FALLBACK: TokenColors = {
  chart: [
    "oklch(0.64 0.17 248)",
    "oklch(0.62 0.16 150)",
    "oklch(0.66 0.21 38)",
    "oklch(0.56 0.19 288)",
    "oklch(0.68 0.2 345)",
  ],
  foreground: "oklch(0.2 0 0)",
  muted: "oklch(0.55 0 0)",
  border: "oklch(0.9 0 0)",
  card: "oklch(1 0 0)",
};

const read = (style: CSSStyleDeclaration, name: string, fallback: string) =>
  style.getPropertyValue(name).trim() || fallback;

/**
 * Reads the chart and ink tokens that apply at `ref`, so a canvas paints in
 * the same colours as the rest of the block. It reads again when the theme
 * or the design system changes the root's class or attributes.
 */
export function useTokenColors(ref: RefObject<Element | null>): TokenColors {
  const [colors, setColors] = useState<TokenColors>(FALLBACK);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const update = () => {
      const style = getComputedStyle(node);
      setColors({
        chart: [
          read(style, "--chart-1", FALLBACK.chart[0]),
          read(style, "--chart-2", FALLBACK.chart[1]),
          read(style, "--chart-3", FALLBACK.chart[2]),
          read(style, "--chart-4", FALLBACK.chart[3]),
          read(style, "--chart-5", FALLBACK.chart[4]),
        ],
        foreground: read(style, "--foreground", FALLBACK.foreground),
        muted: read(style, "--muted-foreground", FALLBACK.muted),
        border: read(style, "--border", FALLBACK.border),
        card: read(style, "--card", FALLBACK.card),
      });
    };
    update();
    const observer = new MutationObserver(update);
    observer.observe(document.documentElement, {
      attributes: true,
      attributeFilter: ["class", "style", "data-theme", "data-ds"],
    });
    return () => observer.disconnect();
  }, [ref]);
  return colors;
}

"use client";

import type { CSSProperties } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatMoney } from "../../lib/format";
import { CITIES } from "./data";

/** Props for the list of the cities that sent the most today. */
export interface CityListProps {
  totals: { revenue: number; payments: number }[];
  selected: number | null;
  onSelect: (city: number | null) => void;
}

const BAR = [
  "bg-chart-1",
  "bg-chart-2",
  "bg-chart-3",
  "bg-chart-4",
  "bg-chart-5",
];

/**
 * The top cities by revenue so far today, each a button that flies the globe
 * there. It is also the text version of the globe for a screen reader.
 */
export function CityList({ totals, selected, onSelect }: CityListProps) {
  const ranked = CITIES.map((city, index) => ({
    city,
    index,
    ...totals[index]!,
  }))
    .sort((a, b) => b.revenue - a.revenue)
    .slice(0, 6);
  const top = Math.max(1, ranked[0]?.revenue ?? 1);
  return (
    <ol
      aria-label="Cities that sent the most today"
      className="flex flex-col gap-0.5"
    >
      {ranked.map((row) => {
        const active = row.index === selected;
        return (
          <li key={row.city.id}>
            <Button
              variant="ghost"
              size="sm"
              aria-pressed={active}
              onClick={() => onSelect(active ? null : row.index)}
              className="relative isolate w-full text-left"
            >
              {active ? (
                <span
                  aria-hidden="true"
                  className="absolute inset-0 -z-10 rounded-lg bg-muted"
                />
              ) : null}
              <span
                className={cn(
                  "flex w-full flex-col gap-1 px-2.5 py-1.5 font-normal",
                  selected !== null && !active && "opacity-60",
                )}
              >
                <span className="flex items-center justify-between gap-3">
                  <span>{row.city.name}</span>
                  <span className="font-medium tabular-nums">
                    {formatMoney(row.revenue)}
                  </span>
                </span>
                <span aria-hidden="true" className="h-1 rounded-full bg-muted">
                  <span
                    className={cn(
                      "block h-full w-(--bar) rounded-full",
                      BAR[row.city.hue - 1],
                    )}
                    // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                    style={
                      {
                        "--bar": `${(row.revenue / top) * 100}%`,
                      } as CSSProperties
                    }
                  />
                </span>
              </span>
            </Button>
          </li>
        );
      })}
    </ol>
  );
}

