// How likely a visit is at each local hour: clinics open from 8 to 19 with a lunch dip.
const LOCAL_DAY = [
  0, 0, 0, 0, 0, 0, 0, 0.2, 0.7, 1, 0.95, 0.85, 0.5, 0.7, 0.9, 0.9, 0.8, 0.6,
  0.35, 0.1, 0, 0, 0, 0,
];

function makePayments(): GlobePayment[] {
  const random = seededRandom(42);
  const payments: GlobePayment[] = [];
  CITIES.forEach((city, cityIndex) => {
    for (let minute = 0; minute < DAY_MINUTES; minute += 10) {
      const local = Math.floor((((minute / 60 + city.offset) % 24) + 24) % 24);
      const chance = (LOCAL_DAY[local] ?? 0) * city.clinics * 0.06;
      if (random() < chance) {
        payments.push({
          city: cityIndex,
          minute: minute + Math.floor(random() * 10),
          amount: 25 + Math.round(random() * 9) * 15,
        });
      }
    }
  });
  return payments.sort((a, b) => a.minute - b.minute);
}

/** Every payment of the day, in time order. */
export const PAYMENTS = makePayments();

/** Writes minutes after midnight as "16:40". */
export const clockLabel = (minute: number) => {
  const whole = Math.min(DAY_MINUTES - 1, Math.max(0, Math.floor(minute)));
  return `${String(Math.floor(whole / 60)).padStart(2, "0")}:${String(whole % 60).padStart(2, "0")}`;
};

/** The day's revenue and payments up to `minute`, in total, per hour and per city. */
export function readDay(minute: number) {
  const hours = Array.from({ length: 24 }, () => 0);
  const cities = CITIES.map(() => ({ revenue: 0, payments: 0 }));
  let revenue = 0;
  let count = 0;
  for (const payment of PAYMENTS) {
    if (payment.minute > minute) break;
    revenue += payment.amount;
    count += 1;
    hours[Math.floor(payment.minute / 60)]! += payment.amount;
    const city = cities[payment.city]!;
    city.revenue += payment.amount;
    city.payments += 1;
  }
  return { revenue, count, hours, cities };
}

/** Each hour's revenue over the whole day, so the timeline keeps one scale while it fills. */
export const FULL_DAY_HOURS = readDay(DAY_MINUTES).hours;

/**
 * Plot maths shared by the blocks. Every path is drawn in a 0 to 100 box, and
 * the SVG stretches it with `preserveAspectRatio="none"`, so a chart needs no
 * resize observer. Strokes keep their width through `vector-effect`.
 */

/** A repeatable random source, so sample data is the same on the server and in the browser. */
export function seededRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state * 1664525 + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

// Monday to Sunday: a working week that tails off, then a quiet weekend.
const WEEKDAY_LIFT = [0.35, 0.5, 0.2, 0.1, -0.05, -0.75, -1];

/** Sample data that moves from `start` to `end` with a working-week rhythm and some noise. */
export function makeSeries(seed: number, length: number, start: number, end: number, noise: number): number[] {
  const random = seededRandom(seed);
  return Array.from({ length }, (_, index) => {
    const progress = length === 1 ? 1 : index / (length - 1);
    const trend = start + (end - start) * progress;
    const week = (WEEKDAY_LIFT[index % 7] ?? 0) * noise * 0.6;
    return Math.max(0, trend + week + (random() - 0.5) * noise * 0.7);
  });
}

/** The lowest and highest value across several series, padded so a line never touches the frame. */
export function paddedExtent(series: number[][], padding = 0.12): [number, number] {
  const values = series.flat();
  const low = Math.min(...values);
  const high = Math.max(...values);
  const span = high - low || 1;
  return [Math.max(0, low - span * padding), high + span * padding];
}

/** Where a value sits in the box, from 0 at the top to 100 at the bottom. */
export function toY(value: number, [low, high]: [number, number]): number {
  return 100 - ((value - low) / (high - low || 1)) * 100;
}

/** Where a point sits across the box, from 0 to 100. */
export function toX(index: number, length: number): number {
  return length <= 1 ? 50 : (index / (length - 1)) * 100;
}

/** The value at a fractional position along a series, read off the straight line between its neighbours. */
function valueAt(values: number[], position: number): number {
  const left = Math.floor(position);
  const right = Math.min(values.length - 1, left + 1);
  const from = values[left] ?? 0;
  const to = values[right] ?? from;
  return from + (to - from) * (position - left);
}

/**
 * A line through `values` with a fixed number of segments. Two paths with the
 * same segment count can morph into each other, whatever their point counts.
 */
export function linePath(values: number[], extent: [number, number], samples = 60): string {
  if (values.length === 0) return "";
  const parts: string[] = [];
  for (let step = 0; step <= samples; step += 1) {
    const position = (step / samples) * (values.length - 1);
    const x = (step / samples) * 100;
    const y = toY(valueAt(values, position), extent);
    parts.push(`${step === 0 ? "M" : "L"}${x.toFixed(2)} ${y.toFixed(2)}`);
  }
  return parts.join(" ");
}

/** The same line, closed down to the bottom edge, for a filled area. */
export function areaPath(values: number[], extent: [number, number], samples = 60): string {
  const line = linePath(values, extent, samples);
  return line ? `${line} L100 100 L0 100 Z` : "";
}

/** Round axis values between the low and high of the plot. */
export function axisTicks([low, high]: [number, number], count = 4): number[] {
  return Array.from({ length: count }, (_, index) => low + ((high - low) * index) / (count - 1));
}

/** The percent change from `before` to `after`, or 0 when there is nothing to compare against. */
export function percentChange(before: number, after: number): number {
  return before === 0 ? 0 : ((after - before) / before) * 100;
}

/** The sum of a series. */
export function sum(values: number[]): number {
  return values.reduce((total, value) => total + value, 0);
}

/** The mean of a series. */
export function mean(values: number[]): number {
  return values.length === 0 ? 0 : sum(values) / values.length;
}

"use client";

import {
  type CSSProperties,
  type KeyboardEvent,
  type PointerEvent,
  useRef,
} from "react";

import { cn } from "@/lib/utils";

import { formatMoney } from "../../lib/format";
import { clockLabel, DAY_MINUTES, FULL_DAY_HOURS } from "./data";

/** Props for the day's bar chart and its time slider. */
export interface DayTimelineProps {
  minute: number;
  liveMinute: number;
  /** Revenue per hour so far. */
  hours: number[];
  onScrub: (minute: number) => void;
  onLive: () => void;
}

const PEAK = Math.max(...FULL_DAY_HOURS);

/**
 * Revenue per hour across the day, with a slider that sets the time the
 * globe shows. Arrows move five minutes, Shift with an arrow or a Page key
 * moves an hour, Home goes to midnight and End returns to live.
 */
export function DayTimeline({
  minute,
  liveMinute,
  hours,
  onScrub,
  onLive,
}: DayTimelineProps) {
  const dragging = useRef(false);
  const toMinute = (event: PointerEvent<HTMLDivElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    return ((event.clientX - box.left) / box.width) * DAY_MINUTES;
  };
  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    const step = event.shiftKey ? 60 : 5;
    if (event.key === "ArrowLeft" || event.key === "ArrowDown")
      onScrub(minute - step);
    else if (event.key === "ArrowRight" || event.key === "ArrowUp")
      onScrub(minute + step);
    else if (event.key === "PageDown") onScrub(minute - 60);
    else if (event.key === "PageUp") onScrub(minute + 60);
    else if (event.key === "Home") onScrub(0);
    else if (event.key === "End") onLive();
    else return;
    event.preventDefault();
  };
  const position = (minute / DAY_MINUTES) * 100;
  const livePosition = (liveMinute / DAY_MINUTES) * 100;

  return (
    <div className="px-5 pb-5">
      <div
        role="slider"
        tabIndex={0}
        aria-label="Time of day"
        aria-valuemin={0}
        aria-valuemax={Math.floor(liveMinute)}
        aria-valuenow={Math.floor(minute)}
        aria-valuetext={`${clockLabel(minute)}, ${formatMoney(hours.reduce((sum, value) => sum + value, 0))} so far`}
        className="relative h-20 cursor-ew-resize touch-pan-y rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-ring"
        onKeyDown={onKeyDown}
        onPointerDown={(event) => {
          dragging.current = true;
          event.currentTarget.setPointerCapture(event.pointerId);
          onScrub(toMinute(event));
        }}
        onPointerMove={(event) => dragging.current && onScrub(toMinute(event))}
        onPointerUp={() => (dragging.current = false)}
        onPointerCancel={() => (dragging.current = false)}
      >
        <div
          aria-hidden="true"
          className="absolute inset-x-0 top-0 bottom-5 flex items-end gap-0.5"
        >
          {FULL_DAY_HOURS.map((full, hour) => {
            const sofar = hours[hour] ?? 0;
            return (
              <div key={hour} className="relative flex h-full flex-1 items-end">
                <span
                  className="absolute inset-x-0 bottom-0 h-(--full) rounded-t-sm bg-muted"
                  // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                  style={
                    { "--full": `${(full / PEAK) * 100}%` } as CSSProperties
                  }
                />
                <span
                  className={cn(
                    "absolute inset-x-0 bottom-0 h-(--sofar) rounded-t-sm",
                    hour % 2 === 0 ? "bg-chart-1" : "bg-chart-4",
                  )}
                  // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
                  style={
                    { "--sofar": `${(sofar / PEAK) * 100}%` } as CSSProperties
                  }
                />
              </div>
            );
          })}
        </div>
        <span
          aria-hidden="true"
          className="absolute top-0 bottom-5 left-(--at) w-px bg-chart-3"
          // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
          style={{ "--at": `${livePosition}%` } as CSSProperties}
        />
        <span
          aria-hidden="true"
          className="absolute top-0 bottom-5 left-(--at) w-0.5 -translate-x-1/2 rounded-full bg-foreground"
          // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
          style={{ "--at": `${position}%` } as CSSProperties}
        />
        <div
          aria-hidden="true"
          className="absolute inset-x-0 bottom-0 flex justify-between text-xs text-muted-foreground"
        >
          <span>00:00</span>
          <span>06:00</span>
          <span>12:00</span>
          <span>18:00</span>
          <span>24:00</span>
        </div>
      </div>
    </div>
  );
}

"use client";

import {
  type KeyboardEvent,
  type PointerEvent,
  useEffect,
  useRef,
  useState,
} from "react";

import { formatMoney, formatWhole } from "../../lib/format";
import { PointTip } from "../../parts/point-tip";
import { clamp, springAt, stepSpring } from "../lib/spring";
import { useCanvasSize } from "../lib/use-canvas-size";
import { useFrameLoop } from "../lib/use-frame-loop";
import type { TokenColors } from "../lib/use-token-colors";
import { CITIES, clockLabel, HEAD_OFFICE, PAYMENTS } from "./data";
import { makeDots, projectVector, radians, slerp, toVector } from "./sphere";

/** Props for the drawn globe. */
export interface GlobeCanvasProps {
  minute: number;
  selected: number | null;
  onSelect: (city: number | null) => void;
  /** Revenue and payment counts per city so far today, for the tooltip. */
  cityTotals: { revenue: number; payments: number }[];
  colors: TokenColors;
  reduceMotion: boolean;
  active: boolean;
  label: string;
}

interface Arc {
  city: number;
  born: number;
}

const DOTS = makeDots(3200);
const HQ = toVector(HEAD_OFFICE.lat, HEAD_OFFICE.lon);
const CITY_VECTORS = CITIES.map((city) => toVector(city.lat, city.lon));
const LAT_LIMIT = 0.85;
const ARC_MS = 1500;
const DRIFT = 0.05;

// Takes the short way round to a longitude, so a flight never spins the long way.
const nearestTurn = (from: number, to: number) =>
  from +
  ((((to - from + Math.PI) % (2 * Math.PI)) + 2 * Math.PI) % (2 * Math.PI)) -
  Math.PI;

/**
 * The globe on a canvas: dotted land, one point per city, and an arc for
 * each payment as it flies to the head office. It drifts on its own, a drag
 * spins it and springs back past the latitude limit, and arrows spin it from
 * the keyboard. With reduced motion it stands still and the arcs of the
 * last minutes stay drawn.
 */
export function GlobeCanvas({
  minute,
  selected,
  onSelect,
  cityTotals,
  colors,
  reduceMotion,
  active,
  label,
}: GlobeCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const size = useCanvasSize(canvasRef);
  const view = useRef({
    lon: springAt(radians(HEAD_OFFICE.lon) - 0.4),
    lat: springAt(radians(HEAD_OFFICE.lat) - 0.35),
  });
  const goal = useRef({
    lon: view.current.lon.value,
    lat: view.current.lat.value,
  });
  const drag = useRef<{ x: number; y: number; moved: boolean } | null>(null);
  const arcs = useRef<Arc[]>([]);
  const lastMinute = useRef(minute);
  const tipSpring = useRef({ x: springAt(50), y: springAt(50) });
  const [hovered, setHovered] = useState<number | null>(null);
  const [tip, setTip] = useState<{ x: number; y: number } | null>(null);
  const [wake, setWake] = useState(0);
  const shown = hovered ?? selected;

  // Each payment whose minute the clock just passed sets off an arc. A jump in time starts afresh.
  useEffect(() => {
    const from = lastMinute.current;
    lastMinute.current = minute;
    if (minute < from || minute - from > 30) {
      arcs.current = [];
      return;
    }
    const now = performance.now();
    for (const payment of PAYMENTS) {
      if (payment.minute > minute) break;
      if (payment.minute > from)
        arcs.current.push({
          city: payment.city,
          born: now - Math.random() * 300,
        });
    }
    arcs.current = arcs.current.slice(-80);
  }, [minute]);

  // Picking a city flies the globe to it.
  useEffect(() => {
    if (selected === null) return;
    const city = CITIES[selected]!;
    goal.current = {
      lon: nearestTurn(view.current.lon.value, radians(city.lon)),
      lat: clamp(radians(city.lat), -LAT_LIMIT, LAT_LIMIT),
    };
  }, [selected]);

  const draw = (seconds: number) => {
    const canvas = canvasRef.current;
    const context = canvas?.getContext("2d");
    if (!canvas || !context || size.width === 0) return false;
    const spring = view.current;
    let moving = false;
    if (!drag.current) {
      if (!reduceMotion && selected === null)
        goal.current.lon += DRIFT * seconds;
      for (const key of ["lon", "lat"] as const) {
        if (reduceMotion) spring[key].value = goal.current[key];
        else if (stepSpring(spring[key], goal.current[key], seconds, 60, 16))
          moving = true;
      }
    }
    const { width, height, ratio } = size;
    const radius = Math.min(width, height) * 0.42;
    const cx = width / 2;
    const cy = height / 2;
    const at = { lon: spring.lon.value, lat: spring.lat.value };
    context.setTransform(ratio, 0, 0, ratio, 0, 0);
    context.clearRect(0, 0, width, height);

    context.globalAlpha = 0.07;
    context.fillStyle = colors.chart[0];
    context.beginPath();
    context.arc(cx, cy, radius, 0, Math.PI * 2);
    context.fill();

    for (const dot of DOTS) {
      const point = projectVector(dot.vector, at, radius, cx, cy);
      if (point.z <= 0) continue;
      context.globalAlpha = dot.land ? 0.3 + 0.6 * point.z : 0.22 * point.z;
      context.fillStyle = dot.land ? colors.foreground : colors.muted;
      const side = dot.land ? 2.2 : 1.2;
      context.fillRect(point.x - side / 2, point.y - side / 2, side, side);
    }

    const now = performance.now();
    const kept: Arc[] = [];
    const drawArc = (
      city: number,
      head: number,
      tail: number,
      alpha: number,
    ) => {
      const from = CITY_VECTORS[city]!;
      context.globalAlpha = alpha;
      context.strokeStyle = colors.chart[CITIES[city]!.hue - 1];
      context.lineWidth = 1.6;
      context.beginPath();
      let pen = false;
      for (let step = 0; step <= 28; step++) {
        const t = tail + ((head - tail) * step) / 28;
        const point = projectVector(
          slerp(from, HQ, t),
          at,
          radius,
          cx,
          cy,
          Math.sin(Math.PI * t) * 0.22,
        );
        if (!point.visible) {
          pen = false;
          continue;
        }
        if (pen) context.lineTo(point.x, point.y);
        else context.moveTo(point.x, point.y);
        pen = true;
      }
      context.stroke();
    };
    if (reduceMotion) {
      const recent = new Set(
        PAYMENTS.filter(
          (payment) => payment.minute <= minute && payment.minute > minute - 12,
        ).map((payment) => payment.city),
      );
      for (const city of recent) drawArc(city, 1, 0, 0.6);
    } else {
      for (const arc of arcs.current) {
        const age = (now - arc.born) / ARC_MS;
        if (age > 1.4 || age < 0) {
          if (age < 0) kept.push(arc);
          continue;
        }
        kept.push(arc);
        drawArc(
          arc.city,
          Math.min(1, age / 0.75),
          Math.max(0, (age - 0.45) / 0.75),
          age > 1 ? (1.4 - age) * 2.5 : 1,
        );
      }
      arcs.current = kept;
      if (kept.length > 0) moving = true;
    }

    CITIES.forEach((city, index) => {
      const point = projectVector(CITY_VECTORS[index]!, at, radius, cx, cy);
      if (point.z <= 0) return;
      context.globalAlpha = 1;
      context.fillStyle = colors.chart[city.hue - 1];
      context.beginPath();
      context.arc(point.x, point.y, index === shown ? 5 : 3.2, 0, Math.PI * 2);
      context.fill();
      if (index === shown) {
        context.strokeStyle = colors.foreground;
        context.lineWidth = 1.5;
        context.stroke();
      }
    });
    const office = projectVector(HQ, at, radius, cx, cy);
    if (office.z > 0) {
      context.globalAlpha = 1;
      context.strokeStyle = colors.foreground;
      context.lineWidth = 2;
      context.beginPath();
      context.arc(office.x, office.y, 6, 0, Math.PI * 2);
      context.stroke();
      context.fillStyle = colors.foreground;
      context.beginPath();
      context.arc(office.x, office.y, 2.5, 0, Math.PI * 2);
      context.fill();
    }

    // The tooltip trails the city on a spring, so it glides instead of jumping between cities.
    if (shown !== null) {
      const point = projectVector(CITY_VECTORS[shown]!, at, radius, cx, cy);
      const tipGoal = {
        x: (point.x / width) * 100,
        y: (point.y / height) * 100,
      };
      const tipNow = tipSpring.current;
      if (reduceMotion) {
        tipNow.x.value = tipGoal.x;
        tipNow.y.value = tipGoal.y;
      } else {
        if (stepSpring(tipNow.x, tipGoal.x, seconds, 210, 24)) moving = true;
        if (stepSpring(tipNow.y, tipGoal.y, seconds, 210, 24)) moving = true;
      }
      setTip(point.z > 0 ? { x: tipNow.x.value, y: tipNow.y.value } : null);
    } else setTip(null);

    return moving || (!reduceMotion && selected === null);
  };

  useFrameLoop(
    draw,
    active,
    `${wake}-${size.width}-${colors.foreground}-${reduceMotion}-${selected}-${shown}-${minute}`,
  );

  const cityAt = (event: PointerEvent<HTMLCanvasElement>) => {
    const box = event.currentTarget.getBoundingClientRect();
    const px = event.clientX - box.left;
    const py = event.clientY - box.top;
    const radius = Math.min(box.width, box.height) * 0.42;
    let best: number | null = null;
    let bestDistance = 18;
    CITY_VECTORS.forEach((vector, index) => {
      const point = projectVector(
        vector,
        { lon: view.current.lon.value, lat: view.current.lat.value },
        radius,
        box.width / 2,
        box.height / 2,
      );
      const distance = Math.hypot(point.x - px, point.y - py);
      if (point.z > 0 && distance < bestDistance) {
        best = index;
        bestDistance = distance;
      }
    });
    return best;
  };

  const onPointerDown = (event: PointerEvent<HTMLCanvasElement>) => {
    drag.current = { x: event.clientX, y: event.clientY, moved: false };
    event.currentTarget.setPointerCapture(event.pointerId);
  };
  const onPointerMove = (event: PointerEvent<HTMLCanvasElement>) => {
    const state = drag.current;
    if (!state) {
      if (event.pointerType === "mouse") setHovered(cityAt(event));
      return;
    }
    const dx = event.clientX - state.x;
    const dy = event.clientY - state.y;
    if (!state.moved && Math.hypot(dx, dy) < 4) return;
    const radius = Math.min(size.width, size.height) * 0.42 || 1;
    const spring = view.current;
    spring.lon.value -= dx / radius;
    const lat = spring.lat.value + dy / radius;
    // Past the limit the globe follows the finger at a third of the distance, then springs back on release.
    const excess = Math.abs(lat) - LAT_LIMIT;
    spring.lat.value =
      excess > 0
        ? Math.sign(lat) * (LAT_LIMIT + Math.min(0.3, excess * 0.35))
        : lat;
    drag.current = { x: event.clientX, y: event.clientY, moved: true };
    setWake((count) => count + 1);
  };
  const onPointerUp = (event: PointerEvent<HTMLCanvasElement>) => {
    const state = drag.current;
    drag.current = null;
    if (!state) return;
    const spring = view.current;
    goal.current = {
      lon: spring.lon.value,
      lat: clamp(spring.lat.value, -LAT_LIMIT, LAT_LIMIT),
    };
    if (!state.moved) onSelect(cityAt(event));
    setWake((count) => count + 1);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLCanvasElement>) => {
    const target = goal.current;
    if (event.key === "ArrowLeft") target.lon -= 0.3;
    else if (event.key === "ArrowRight") target.lon += 0.3;
    else if (event.key === "ArrowUp")
      target.lat = clamp(target.lat - 0.2, -LAT_LIMIT, LAT_LIMIT);
    else if (event.key === "ArrowDown")
      target.lat = clamp(target.lat + 0.2, -LAT_LIMIT, LAT_LIMIT);
    else if (event.key === "Escape" && selected !== null) onSelect(null);
    else return;
    event.preventDefault();
    setWake((count) => count + 1);
  };

  const city = shown === null ? null : CITIES[shown]!;
  const totals = shown === null ? null : cityTotals[shown];
  const localMinute = city
    ? (((minute + city.offset * 60) % 1440) + 1440) % 1440
    : 0;

  return (
    <div className="relative aspect-square w-full max-w-md justify-self-center">
      <canvas
        ref={canvasRef}
        role="application"
        aria-roledescription="globe"
        aria-label={label}
        tabIndex={0}
        className="size-full cursor-grab touch-pan-y rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring active:cursor-grabbing"
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={() => (drag.current = null)}
        onPointerLeave={(event) =>
          event.pointerType === "mouse" && setHovered(null)
        }
        onKeyDown={onKeyDown}
      />
      {city && totals && tip ? (
        <PointTip
          x={tip.x}
          y={tip.y}
          title={`${city.name}, ${clockLabel(localMinute)} there`}
          rows={[
            {
              label: "Revenue today",
              value: formatMoney(totals.revenue),
              marker: `bg-chart-${city.hue}`,
            },
            { label: "Payments", value: formatWhole(totals.payments) },
          ]}
        />
      ) : null}
    </div>
  );
}

import { cn } from "@/lib/utils";

import type { VarStyle } from "@/components/blocks/lib/css-vars";
import { RollingText } from "./rolling-text";

/** One line of a point's details. */
export interface PointTipRow {
  label: string;
  value: string;
  /** A class that colours the row's marker, such as `bg-chart-1`. Omit for a row with no series. */
  marker?: string;
  /** Draws the marker as a dashed line, for an earlier period. */
  dashed?: boolean;
}

/** Props for the card that shows one point's details. */
export interface PointTipProps {
  /** Where the point sits in its plot, from 0 to 100 on each axis, measured from the top left. */
  x: number;
  y: number;
  title: string;
  rows: PointTipRow[];
  /** A closing line, such as the difference between two rows. */
  note?: string;
  className?: string;
}

/**
 * A small card beside an inspected point. It sits on the side of the point
 * with more room and stays inside the plot. In a plot narrower than the card
 * and the point together, it may cover the point rather than be cut off.
 * The digits of each value roll to the next point's figure as the point changes.
 * The card blurs what is behind it, so a design system with a see-through popover stays legible.
 * It is decorative for screen readers: the plot's live readout says the same.
 */
export function PointTip({ x, y, title, rows, note, className }: PointTipProps) {
  const onLeft = x > 55;
  return (
    <div
      aria-hidden="true"
      className={cn("pointer-events-none absolute top-(--y) z-10", onLeft ? "right-(--side)" : "left-(--side)", className)}
      style={
        // SAFETY: the object holds only CSS custom properties, which CSSProperties does not list.
        {
          // The card hangs one rem from the point, but never past the plot's edge: 14rem is its widest.
          "--side": `min(calc(${onLeft ? 100 - x : x}% + 1rem), calc(100% - 14rem))`,
          "--y": `${Math.min(78, Math.max(22, y))}%`,
        } as VarStyle
      }
    >
      <div
        className={cn(
          "flex w-max max-w-56 -translate-y-1/2 flex-col gap-1.5 rounded-xl border border-border bg-popover px-3 py-2 text-popover-foreground shadow-lg backdrop-blur-md",
        )}
      >
        <span className="text-xs text-muted-foreground">{title}</span>
        {rows.map((row) => (
          <span key={row.label} className="flex items-center justify-between gap-6 text-sm">
            <span className="flex items-center gap-2 text-muted-foreground">
              {row.marker ? (
                <span className={cn("h-0.5 w-3 rounded-full", row.dashed ? "border-t border-dashed border-current" : row.marker)} />
              ) : null}
              {row.label}
            </span>
            <RollingText text={row.value} className="font-medium" />
          </span>
        ))}
        {note ? <span className="border-t border-border pt-1.5 text-xs text-muted-foreground">{note}</span> : null}
      </div>
    </div>
  );
}

import type { CSSProperties } from "react";

/**
 * An inline style made only of custom properties, for values known at render
 * such as a point's place in a plot. Classes read them, as `left-(--x)` does.
 */
export type VarStyle = CSSProperties & { [name: `--${string}`]: string | number };

/** One value pulled toward a target by a spring, with the speed it carries. */
export interface SpringValue {
  value: number;
  velocity: number;
}

/**
 * Moves a spring one step toward `target`. The defaults are close to
 * critically damped, so a value arrives quickly and barely overshoots.
 * Returns true while the value is still moving.
 */
export function stepSpring(
  spring: SpringValue,
  target: number,
  seconds: number,
  stiffness = 170,
  damping = 26,
): boolean {
  // Small sub-steps keep a stiff spring stable on a slow frame.
  const steps = Math.max(1, Math.ceil(seconds / 0.008));
  const dt = seconds / steps;
  for (let index = 0; index < steps; index++) {
    const force =
      (target - spring.value) * stiffness - spring.velocity * damping;
    spring.velocity += force * dt;
    spring.value += spring.velocity * dt;
  }
  const moving =
    Math.abs(target - spring.value) > 0.0005 ||
    Math.abs(spring.velocity) > 0.0005;
  if (!moving) {
    spring.value = target;
    spring.velocity = 0;
  }
  return moving;
}

/** Makes a spring that rests at `value`. */
export const springAt = (value: number): SpringValue => ({
  value,
  velocity: 0,
});

/** Eases a value from 0 to 1 slowly at both ends. */
export const easeInOut = (t: number) =>
  t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2;

/** Keeps a value between two bounds. */
export const clamp = (value: number, low: number, high: number) =>
  Math.min(high, Math.max(low, value));

"use client";

import { type RefObject, useEffect, useState } from "react";

/** The drawing size of a canvas in CSS pixels, and the device ratio it is painted at. */
export interface CanvasSize {
  width: number;
  height: number;
  ratio: number;
}

/**
 * Watches a canvas's box and sizes its bitmap to match the screen's pixel
 * ratio, capped at 2 to keep each frame cheap. Returns the box in CSS pixels.
 */
export function useCanvasSize(
  ref: RefObject<HTMLCanvasElement | null>,
): CanvasSize {
  const [size, setSize] = useState<CanvasSize>({
    width: 0,
    height: 0,
    ratio: 1,
  });
  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return;
      const ratio = Math.min(2, window.devicePixelRatio || 1);
      const { width, height } = entry.contentRect;
      canvas.width = Math.round(width * ratio);
      canvas.height = Math.round(height * ratio);
      setSize({ width, height, ratio });
    });
    observer.observe(canvas);
    return () => observer.disconnect();
  }, [ref]);
  return size;
}

"use client";

import { useEffect, useLayoutEffect, useRef } from "react";

/**
 * Runs `step` once per animation frame while `active` is true. `step` gets the
 * seconds since the last frame, capped so a hidden tab does not jump, and
 * returns false when nothing moves any more, which stops the loop until
 * `wake` changes. The latest `step` always runs, so it may read fresh state.
 */
export function useFrameLoop(
  step: (seconds: number) => boolean,
  active: boolean,
  wake: string | number | null = null,
) {
  const stepRef = useRef(step);
  useLayoutEffect(() => {
    stepRef.current = step;
  });
  useEffect(() => {
    if (!active) return;
    let frame = 0;
    let last = performance.now();
    const tick = (now: number) => {
      const seconds = Math.min(0.05, (now - last) / 1000);
      last = now;
      if (stepRef.current(seconds)) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [active, wake]);
}

/** A point on or above the globe, in screen units, with whether the viewer can see it. */
export interface GlobePoint {
  x: number;
  y: number;
  /** Positive faces the viewer. */
  z: number;
  visible: boolean;
}

/** Which way the globe faces: the longitude and latitude at its centre, in radians. */
export interface GlobeView {
  lon: number;
  lat: number;
}

const RAD = Math.PI / 180;

type Vector = [number, number, number];

/** Turns a latitude and longitude in degrees into a unit vector. */
export const toVector = (lat: number, lon: number): Vector => [
  Math.cos(lat * RAD) * Math.sin(lon * RAD),
  Math.sin(lat * RAD),
  Math.cos(lat * RAD) * Math.cos(lon * RAD),
];

/**
 * Projects a unit vector, lifted `lift` globe radii above the ground, onto a
 * globe of radius `radius` centred at `cx` and `cy`. A point behind the globe
 * is hidden unless its lift carries it past the rim.
 */
export function projectVector(
  vector: Vector,
  view: GlobeView,
  radius: number,
  cx: number,
  cy: number,
  lift = 0,
): GlobePoint {
  const [x, y, z] = vector;
  const cosLon = Math.cos(view.lon);
  const sinLon = Math.sin(view.lon);
  const x1 = x * cosLon - z * sinLon;
  const z1 = x * sinLon + z * cosLon;
  const cosLat = Math.cos(view.lat);
  const sinLat = Math.sin(view.lat);
  const y2 = y * cosLat - z1 * sinLat;
  const z2 = y * sinLat + z1 * cosLat;
  const scale = radius * (1 + lift);
  const px = x1 * scale;
  const py = y2 * scale;
  const visible = z2 > 0 || px * px + py * py > radius * radius;
  return { x: cx + px, y: cy - py, z: z2, visible };
}

/** Walks the great circle between two unit vectors, `t` from 0 to 1. */
export function slerp(a: Vector, b: Vector, t: number): Vector {
  const dot = Math.min(
    1,
    Math.max(-1, a[0] * b[0] + a[1] * b[1] + a[2] * b[2]),
  );
  const angle = Math.acos(dot);
  if (angle < 1e-6) return a;
  const sin = Math.sin(angle);
  const wa = Math.sin((1 - t) * angle) / sin;
  const wb = Math.sin(t * angle) / sin;
  return [a[0] * wa + b[0] * wb, a[1] * wa + b[1] * wb, a[2] * wa + b[2] * wb];
}

// Rough land, drawn as ovals of latitude and longitude. It is a sketch of the continents, not a map.
const LAND: [number, number, number, number][] = [
  [50, -100, 16, 30],
  [63, -115, 9, 34],
  [31, -95, 9, 17],
  [16, -90, 6, 9],
  [72, -42, 8, 14],
  [-6, -62, 13, 15],
  [-24, -60, 11, 9],
  [-42, -69, 10, 5],
  [49, 12, 9, 17],
  [63, 17, 7, 8],
  [54, -3, 4, 3],
  [12, 12, 13, 22],
  [-9, 25, 13, 12],
  [-26, 25, 8, 9],
  [-19, 47, 5, 3],
  [26, 46, 9, 10],
  [56, 90, 14, 50],
  [36, 102, 12, 24],
  [21, 78, 9, 8],
  [13, 103, 7, 6],
  [37, 138, 6, 3],
  [-3, 115, 4, 14],
  [-25, 134, 10, 17],
  [-41, 173, 5, 3],
];

const isLand = (lat: number, lon: number) =>
  LAND.some(([centreLat, centreLon, spanLat, spanLon]) => {
    const dLon = ((lon - centreLon + 540) % 360) - 180;
    return ((lat - centreLat) / spanLat) ** 2 + (dLon / spanLon) ** 2 <= 1;
  });

/** Evenly spread dots on the sphere, each marked as land or sea. */
export function makeDots(count: number) {
  const golden = Math.PI * (3 - Math.sqrt(5));
  return Array.from({ length: count }, (_, index) => {
    const y = 1 - ((index + 0.5) / count) * 2;
    const lat = Math.asin(y) / RAD;
    const lon = (((((index * golden) / RAD) % 360) + 360) % 360) - 180;
    return { vector: toVector(lat, lon), land: isLand(lat, lon) };
  });
}

/** Converts degrees to radians. */
export const radians = (degrees: number) => degrees * RAD;

"use client";

import { useEffect, useState } from "react";

import { DAY_MINUTES, LIVE_MINUTE } from "./data";

/** Where the clock is and how it moves. */
export interface DayClock {
  /** The minute shown, after midnight. */
  minute: number;
  /** The minute it is now. It keeps moving while the person looks back. */
  liveMinute: number;
  live: boolean;
  playing: boolean;
}

const TICK_MS = 250;
// The sample day runs fast so a visit can watch payments arrive: one minute a second, fifteen in a replay.
const LIVE_SPEED = 1;
const REPLAY_SPEED = 15;

/**
 * The globe's clock. Live follows the present minute. A replay runs the day
 * from midnight at speed and joins live when it catches up. Pause freezes
 * the shown minute, and a scrub sets it by hand. It ticks only while
 * `active` is true.
 */
export function useDayClock(active: boolean) {
  const [clock, setClock] = useState<DayClock>({
    minute: LIVE_MINUTE,
    liveMinute: LIVE_MINUTE,
    live: true,
    playing: true,
  });

  useEffect(() => {
    if (!active) return;
    const id = window.setInterval(() => {
      setClock((current) => {
        const liveMinute = Math.min(
          DAY_MINUTES - 1,
          current.liveMinute + (TICK_MS / 1000) * LIVE_SPEED,
        );
        if (current.live) return { ...current, liveMinute, minute: liveMinute };
        if (!current.playing) return { ...current, liveMinute };
        const minute = current.minute + (TICK_MS / 1000) * REPLAY_SPEED;
        return minute >= liveMinute
          ? { minute: liveMinute, liveMinute, live: true, playing: true }
          : { ...current, liveMinute, minute };
      });
    }, TICK_MS);
    return () => window.clearInterval(id);
  }, [active]);

  const replay = () =>
    setClock((current) => ({
      ...current,
      minute: 0,
      live: false,
      playing: true,
    }));
  const togglePlaying = () =>
    setClock((current) =>
      current.playing
        ? { ...current, playing: false, live: false }
        : {
            ...current,
            playing: true,
            live: current.minute >= current.liveMinute - 0.5,
          },
    );
  const scrub = (minute: number) =>
    setClock((current) => {
      const clamped = Math.max(0, Math.min(current.liveMinute, minute));
      return clamped >= current.liveMinute
        ? { ...current, minute: current.liveMinute, live: true, playing: true }
        : { ...current, minute: clamped, live: false, playing: false };
    });
  const goLive = () =>
    setClock((current) => ({
      ...current,
      minute: current.liveMinute,
      live: true,
      playing: true,
    }));

  return { clock, replay, togglePlaying, scrub, goLive };
}
